export function normalizeLocalAssetPath(rawUrl?: string | null): string | null {
  if (!rawUrl) return null;
  const trimmed = rawUrl.trim();
  if (!trimmed || trimmed.startsWith('data:') || trimmed.startsWith('blob:')) {
    return null;
  }
  let pathname = trimmed;
  if (/^https?:\/\//i.test(trimmed)) {
    try {
      const parsed = new URL(trimmed);
      const host = parsed.hostname.toLowerCase();
      if (
        host !== 'dorasanicollections.com' &&
        host !== 'www.dorasanicollections.com' &&
        host !== 'localhost' &&
        host !== '127.0.0.1'
      ) {
        return null;
      }
      pathname = parsed.pathname;
    } catch {
      return null;
    }
  }
  const clean = pathname.split(/[?#]/)[0];
  if (!clean.startsWith('/assets/')) return null;
  return clean;
}

export function getAssetMeta(rawUrl?: string | null): { path: string; meta: OptimizedAssetMeta } | null {
  const path = normalizeLocalAssetPath(rawUrl);
  if (!path) return null;
  const meta = OPTIMIZED_ASSETS[path];
  if (!meta) return null;
  return { path, meta };
}

export function buildResponsiveSrcSet(
  assetPath: string,
  meta: OptimizedAssetMeta,
  format: 'avif' | 'webp'
): string {
  const dotIdx = assetPath.lastIndexOf('.');
  const stem = dotIdx >= 0 ? assetPath.slice(0, dotIdx) : assetPath;
  return meta.widths
    .map((width) => {
      const url = width === meta.w ? `${stem}.${format}` : `${stem}-${width}w.${format}`;
      return `${url} ${width}w`;
    })
    .join(', ');
}
